import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The ports — where backends meet the substrate","description":"","frontmatter":{},"headers":[],"relativePath":"eqsat/explanation/ports.md","filePath":"vendored/eqsat/explanation/ports.md"}`),a={name:`eqsat/explanation/ports.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="the-ports-—-where-backends-meet-the-substrate" tabindex="-1">The ports — where backends meet the substrate <a class="header-anchor" href="#the-ports-—-where-backends-meet-the-substrate" aria-label="Permalink to “The ports — where backends meet the substrate”">​</a></h1><p>eqsat never imports a backend, and a backend never sees the search. They meet through <code>mlopt_core.ports</code>: a set of <code>Protocol</code> shapes each side implements or consumes. This is the seam the repo split cut along — <code>graphopt</code>&#39;s <code>mlopt_torch</code>/<code>mlopt_onnx</code> adapters are <em>implementations</em> of these ports, not parts of the engine.</p><h2 id="the-contract-surfaces" tabindex="-1">The contract surfaces <a class="header-anchor" href="#the-contract-surfaces" aria-label="Permalink to “The contract surfaces”">​</a></h2><ul><li><strong><code>Source</code></strong> — lifts a domain object (a <code>torch.nn.Module</code>, an ONNX graph) into <code>mlopt_core</code> terms. The substrate sees only terms.</li><li><strong><code>Sink</code></strong> — the way back down: <code>lower</code> emits a runnable artifact, <code>verify</code> checks it against the source, <code>executors</code> lists what can run it — all on top of <strong><code>Capabilities</code></strong>&#39;s <code>supported_ops</code>/<code>ops</code>, the hard feasibility declaration.</li><li><strong><code>Engine</code></strong> — the <code>engine=</code> contract on <code>search</code>: an alternate saturation engine (the PyO3 <code>mlopt_native.NativeEngine</code>). Engines are <strong>never auto-detected</strong> — an <code>Engine</code>-port value is passed explicitly and <code>stats[&quot;engine&quot;]</code> records which ran (<code>&quot;python&quot;</code> reference default, <code>&quot;native&quot;</code> opt-in). The port covers <em>search</em> only — certificates and the non-local passes are Python-engine capabilities.</li><li><strong><code>Runner</code> / <code>Executor</code> / <code>ExecutorSpec</code> / <code>Composer</code></strong> — delivery: how a lowered artifact is executed, timed, and chained.</li><li><strong><code>Policy</code></strong> — <em>orders</em> the saturation schedule (which rules to try first). Every rule still fires, so the fixed point and the certificate are unchanged — a policy can never decide equivalence.</li><li><strong><code>Criterion</code> / <code>CostFn</code> / <code>Strategy</code> / <code>TaskMetric</code></strong> — what &quot;cheapest&quot; means, and the <code>Monolithic</code>/<code>Compositional</code>/<code>Autotuned</code> strategy shapes.</li><li><strong>The rest of the port vocabulary</strong> — <code>Meter</code>, <code>Verifier</code>, <code>VerifyResult</code>, <code>PerformanceModel</code>, <code>Profiler</code>, <code>OpRegistry</code>, <code>RuleSetLike</code>, <code>RuleLike</code>, <code>RuleSetProvider</code>, <code>Binding</code>, <code>TimingResult</code>, <code>signature_conforms</code>.</li></ul><h2 id="the-boundary-honesty" tabindex="-1">The boundary honesty <a class="header-anchor" href="#the-boundary-honesty" aria-label="Permalink to “The boundary honesty”">​</a></h2><p>The port binds <em>shapes</em>, never <em>contents</em>: <code>DOMAINS</code>, <code>ALL_RULES</code>, <code>MACHINE_SHIPPED</code> rows, and the <code>lawdata</code> tables are data — the registries&#39; names are frozen, the rows are each domain repo&#39;s business. Compat re-exports (<code>egraph._term_match</code>, <code>cost._memo_dispatch</code>, …) stay internal even where reachable — &quot;reachable&quot; is not &quot;public&quot;.</p><p>The frozen names are the <a href="./../reference/frozen-api.html">substrate slice of the manifest</a>; the domain-side implementations are documented under <a href="/docs/graphopt/">graphopt</a>.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};